const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=v=>structuredClone(v),safe=s=>String(s).replace(/[^\p{L}\p{N}_-]/gu,'_').slice(0,70),uid=()=>Math.random().toString(36).slice(2,11);
const SUPPORTED={color:['mix','output'],sculpt:['cutoff','highpass'],prism:['low','mid','high','lowFreq','midFreq','highFreq','q'],glue:['threshold','ratio','attack','release','makeup','knee','mix'],echo:['mix','feedback'],aura:['mix'],hush:['threshold'],sibil:['threshold','frequency'],ember:['mix','tone','output'],orbit:['rate','depth','width','mix'],sway:['rate','depth','pan','mix'],relay:['feedback','tone','mix']};
export function automationParameters(track){const list=[{key:'volume',name:'Volume',min:-48,max:12,value:track.volume},{key:'pan',name:'Panoramique',min:-1,max:1,value:track.pan}];for(const s of track.sends||[])list.push({key:'send:'+s.id,name:'Envoi '+s.target,min:-60,max:12,value:s.level});for(const id of track.inserts||[])if(id){const d=effectDefinition(id);for(const c of d.controls)if(SUPPORTED[effectType(id)]?.includes(c.key))list.push({key:id+':'+c.key,name:d.name+' · '+c.name,min:c.min,max:c.max,value:track.effects[id][c.key]});}return list;}
export function installStudioWorkflow(d){
  const p=d.getProject,engine=d.getEngine,assets=d.getAssets,track=()=>d.currentTrack(),clip=()=>d.currentClip();let testGraph=null,snapshotTime=0,stretchWorker=null,exporting=false,preparedExport=null,selectedCurve='volume',curveTrack=null,lastAnalysis=null,analysisProject=null,analysing=false;
  const setup=()=>p().audioSetup??={deviceId:'',channel:'1',monitor:false,latencyMs:0,keepTakes:true};
  function routingHTML(t){return `<div class="workflow-routing"><label>SORTIE<select data-route-output="${t.id}" aria-label="Sortie de ${esc(t.name)}"><option value="master">MASTER 1–2</option>${p().tracks.filter(b=>b.type==='bus'&&routeAllowed(p().tracks,t.id,b.id)).map(b=>`<option value="${b.id}" ${t.output===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><div class="workflow-label">ENVOIS AUXILIAIRES</div>${(t.sends||[]).map(s=>`<div class="aux-send"><div><strong>${esc(p().tracks.find(b=>b.id===s.target)?.name||'Bus')}</strong><button data-send-toggle="${t.id}:${s.id}" aria-label="Activer l’envoi" aria-pressed="${s.enabled}">${s.enabled?'ON':'OFF'}</button><button data-send-remove="${t.id}:${s.id}" aria-label="Retirer l’envoi">×</button></div><input data-send-level="${t.id}:${s.id}" type="range" min="-60" max="12" step=".5" value="${s.level}" aria-label="Niveau d’envoi ${esc(p().tracks.find(b=>b.id===s.target)?.name||'Bus')}"><label><span data-send-db="${s.id}">${s.level.toFixed(1)} dB</span><select data-send-position="${t.id}:${s.id}" aria-label="Position de l’envoi"><option value="post" ${!s.pre?'selected':''}>Post-fader</option><option value="pre" ${s.pre?'selected':''}>Pré-fader</option></select></label></div>`).join('')}<select data-send-add="${t.id}" aria-label="Ajouter un envoi"><option value="">+ Envoi vers un bus…</option>${p().tracks.filter(b=>b.type==='bus'&&routeAllowed(p().tracks,t.id,b.id)&&!(t.sends||[]).some(s=>s.target===b.id)).map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select><button class="outline-btn" data-create-bus>+ Créer un bus / auxiliaire</button></div>`;}
  function renderInspector(){const t=track();if(!t)return;const root=$('trackInspector');root.querySelector('.inspector-route')?.remove();root.querySelector('.workflow-inspector')?.remove();root.insertAdjacentHTML('beforeend',`<div class="workflow-inspector">${routingHTML(t)}<div class="workflow-label">AUTOMATION</div><button class="outline-btn" data-automation-track="${t.id}">${(t.automation?.mode||'off').toUpperCase()} · Éditer les courbes</button>${t.type==='audio'?`<div class="workflow-label">PRISES & MONTAGE</div><button class="outline-btn" data-playlists-track="${t.id}">Prises / comping ${t.playlists?.length?'('+t.playlists.length+')':''}</button>`:''}<button class="outline-btn" data-freeze-track="${t.id}">${t.frozenTrack?'Dégeler la piste':'Geler la piste en audio'}</button></div>`);}
  function renderMixer(){for(const t of p().tracks){const root=document.querySelector(`[data-mixer-track="${t.id}"] .channel-routing`);if(root)root.innerHTML=`<select data-route-output="${t.id}" aria-label="Sortie de ${esc(t.name)}"><option value="master">MASTER 1–2</option>${p().tracks.filter(b=>b.type==='bus'&&routeAllowed(p().tracks,t.id,b.id)).map(b=>`<option value="${b.id}" ${t.output===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><button class="channel-auto" data-automation-track="${t.id}">${(t.automation?.mode||'off').toUpperCase()}</button>`;}}
  function renderAudioEditor(){const c=clip(),t=track();if(t?.type!=='audio'||!c)return;$('editorContent').insertAdjacentHTML('beforeend',`<div class="audio-edit-actions"><button class="outline-btn" data-audio-properties>Fondus / durée / hauteur</button><button class="outline-btn" data-playlists-track="${t.id}">Prises / comping</button><button class="outline-btn" data-crossfade>Fondu croisé</button><button class="outline-btn" data-group-clips>Grouper la sélection</button><button class="outline-btn" data-ungroup-clips>Dégrouper</button><button class="outline-btn" data-batch-gain>Gain de la sélection</button></div>`);}
  function renderTimeline(){for(const t of p().tracks){const row=document.querySelector(`[data-track="${t.id}"] .track-lane`);if(!row)continue;row.querySelector('.automation-lane')?.remove();const points=t.automation?.curves?.volume;if(points?.length&&t.automation.mode!=='off'){const line=points.map(a=>`${a.bar/p().bars*1000},${60-(a.value+48)}`).join(' ');row.insertAdjacentHTML('beforeend',`<svg class="automation-lane" viewBox="0 0 1000 60" preserveAspectRatio="none" aria-label="Automation de volume"><polyline points="${line}"/></svg>`);}}}
  function busModal(){d.modal('Créer un bus / auxiliaire',`<form class="workflow-form" id="busForm"><label>Nom du bus<input id="busName" value="VOX" maxlength="60"></label><p>Ce bus démarre sans plugin. Choisis ensuite les pistes qui doivent y sortir, ou crée un envoi pour un effet parallèle.</p><button type="submit" class="primary-btn">Créer le bus</button></form>`,'WARLIKE / ROUTAGE');$('busForm').onsubmit=e=>{e.preventDefault();const name=$('busName').value.trim()||'BUS',t=d.addTrack('bus');t.name=name;d.changed(true);$('modal').close();};}
  function audioProperties(){const c=clip();if(!c?.audioId){d.toast('Sélectionne un clip audio.');return;}const t=track(),duration=c.length*240/p().bpm;d.modal('Montage · '+c.name,`<div class="workflow-form"><div class="workflow-grid"><label>Fondu d’entrée (ms)<input id="fadeInMs" type="number" min="0" max="${duration*1000}" value="${Math.round((c.fadeIn??.005)*1000)}"></label><label>Fondu de sortie (ms)<input id="fadeOutMs" type="number" min="0" max="${duration*1000}" value="${Math.round((c.fadeOut??.005)*1000)}"></label></div><label>Courbe<select id="fadeShape"><option value="linear">Linéaire</option><option value="equalPower" ${c.fadeCurve==='equalPower'?'selected':''}>Puissance égale</option></select></label><button class="primary-btn" id="applyFades">Appliquer les fondus</button><hr><div class="workflow-grid"><label>Durée cible (mesures)<input id="stretchLength" type="number" min="${c.length*.5}" max="${c.length*2}" step=".001" value="${c.length}"></label><label>Transposition (demi-tons)<input id="transposeSemitones" type="number" min="-12" max="12" step="1" value="0"></label></div><p>Étirement WSOLA de 50 à 200 %, hauteur conservée. Pour une voix, TUNE reste disponible séparément. L’original est conservé ; les transitoires et les sons complexes peuvent demander un autre réglage.</p><button class="outline-btn" id="applyStretch">Calculer le nouvel audio</button><button class="text-btn" id="cancelStretch" hidden>Annuler le calcul</button>${c.editOriginal?'<button class="outline-btn" id="restoreEditSource">Restaurer l’audio avant étirement</button>':''}<output id="stretchProgress"></output></div>`,'WARLIKE / AUDIO');
    $('applyFades').onclick=()=>{d.checkpoint();c.fadeIn=Math.max(0,Math.min(duration,Number($('fadeInMs').value)/1000||0));c.fadeOut=Math.max(0,Math.min(duration,Number($('fadeOutMs').value)/1000||0));c.fadeCurve=$('fadeShape').value;d.changed(true);$('modal').close();};
    if($('restoreEditSource'))$('restoreEditSource').onclick=()=>{d.checkpoint();const old=clone(c.editOriginal);Object.assign(c,old);delete c.editOriginal;d.changed(true);$('modal').close();};
    $('applyStretch').onclick=()=>{if(stretchWorker)return;const a=assets().get(c.audioId);if(!a)return;const newLength=Number($('stretchLength').value),ratio=newLength/c.length,semitones=Number($('transposeSemitones').value);if(!Number.isFinite(ratio)||ratio<.5||ratio>2||!Number.isFinite(semitones)||Math.abs(semitones)>12||duration>300){d.toast('Choisis une durée de 50 à 200 %, un clip de moins de cinq minutes et une transposition de −12 à +12.');return;}const n=Math.min(Math.round(duration*a.buffer.sampleRate),a.buffer.length-Math.round((c.sourceOffset||0)*a.buffer.sampleRate));if(n<1)return;const channels=Array.from({length:a.buffer.numberOfChannels},(_,i)=>a.buffer.getChannelData(i).slice(Math.round((c.sourceOffset||0)*a.buffer.sampleRate),Math.round((c.sourceOffset||0)*a.buffer.sampleRate)+n));
      stretchWorker=new Worker(new URL('./stretch-worker.js?v=0.13.0',import.meta.url),{type:'module'});$('applyStretch').disabled=true;$('cancelStretch').hidden=false;
      const done=()=>{stretchWorker?.terminate();stretchWorker=null;if($('applyStretch'))$('applyStretch').disabled=false;if($('cancelStretch'))$('cancelStretch').hidden=true;};
      $('cancelStretch').onclick=()=>{done();if($('stretchProgress'))$('stretchProgress').textContent='Calcul annulé.';};
      stretchWorker.onmessage=async({data})=>{if(data.progress!==undefined){if($('stretchProgress'))$('stretchProgress').textContent=data.progress+' %';return;}if(data.error){done();d.toast(data.error);return;}done();try{await engine().init();const buffer=engine().ctx.createBuffer(data.channels.length,data.channels[0].length,a.buffer.sampleRate);data.channels.forEach((ch,i)=>buffer.copyToChannel(ch,i));d.checkpoint();const original=c.editOriginal||clone(c),id=uid();assets().set(id,{name:c.name+' · montage',buffer,data:encodeWav(buffer,{bits:32})});c.editOriginal=original;c.audioId=id;c.sourceOffset=0;c.length=buffer.duration/(240/p().bpm);p().bars=fitSession(p().bars,c.start+c.length);d.changed(true);$('modal').close();d.toast('Nouvel audio calculé. L’original reste récupérable.');}catch(error){d.toast(error.message);}};
      stretchWorker.onerror=()=>{done();d.toast('Le calcul audio a échoué.');};stretchWorker.postMessage({channels,sampleRate:a.buffer.sampleRate,ratio,semitones},channels.map(c=>c.buffer));
    };
  }
  function playlistsModal(id){const t=p().tracks.find(t=>t.id===id);if(t?.type!=='audio')return;ensurePlaylists(t,uid);saveActivePlaylist(t);d.save();
    d.modal('Prises · '+t.name,`<div class="workflow-form"><label>Playlist écoutée<select id="activePlaylist" aria-label="Playlist active">${t.playlists.map(l=>`<option value="${l.id}" ${l.id===t.activePlaylist?'selected':''}>${esc(l.name)} · ${l.clips.length} clip(s)</option>`).join('')}</select></label><label>Nom<input id="playlistName" value="${esc(t.playlists.find(l=>l.id===t.activePlaylist).name)}" maxlength="60"></label><div class="workflow-row"><button class="outline-btn" id="renamePlaylist">Renommer</button><button class="outline-btn" id="copyPlaylist">Dupliquer la playlist</button><button class="outline-btn" id="emptyPlaylist">Nouvelle playlist vide</button></div><hr><strong>COMPING · Remplacer une plage par une autre prise</strong><label>Prise source<select id="compSource">${t.playlists.filter(l=>l.id!==t.activePlaylist).map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></label><div class="workflow-grid"><label>Début (mesure)<input id="compStart" type="number" step=".0625" min="1" value="${clip()?.start+1||engine().getPosition()/16+1}"></label><label>Fin (mesure)<input id="compEnd" type="number" step=".0625" min="1" value="${clip()?clip().start+clip().length+1:engine().getPosition()/16+2}"></label></div><button class="primary-btn" id="applyComp" ${t.playlists.length<2?'disabled':''}>Utiliser cette plage dans la playlist active</button><p>Les autres playlists restent intactes. Les découpes conservent leurs références audio ; de courts fondus sont ajoutés aux nouvelles coupes. Pendant une nouvelle prise superposée, une playlist est créée automatiquement si l’option est activée.</p></div>`,'WARLIKE / PLAYLISTS');
    $('activePlaylist').onchange=e=>{engine().pause();d.checkpoint();switchPlaylist(t,e.target.value);d.selectTrack(t.id,t.clips[0]?.id);d.changed(true);playlistsModal(t.id);};
    $('renamePlaylist').onclick=()=>{d.checkpoint();t.playlists.find(l=>l.id===t.activePlaylist).name=$('playlistName').value.trim()||'Prise';d.changed();playlistsModal(t.id);};
    for(const [id,empty] of [['copyPlaylist',false],['emptyPlaylist',true]])$(id).onclick=()=>{engine().pause();d.checkpoint();newPlaylist(t,uid,{empty,name:'Prise '+(t.playlists.length+1)});d.selectTrack(t.id,t.clips[0]?.id);d.changed(true);playlistsModal(t.id);};
    $('applyComp').onclick=()=>{try{const start=Number($('compStart').value)-1,end=Number($('compEnd').value)-1;if(end>p().bars)throw Error('La plage dépasse la session.');d.checkpoint();const pieces=compPlaylist(t,$('compSource').value,start,end,p().bpm,uid);d.selectTrack(t.id,pieces[0].id);d.changed(true);$('modal').close();d.toast('Comping appliqué ; les prises source sont conservées.');}catch(error){d.toast(error.message);}};
  }
  function automationModal(id,key='volume'){
    const t=p().tracks.find(t=>t.id===id);if(!t)return;t.automation??={mode:'off',curves:{}};t.automation.curves??={};curveTrack=id;const params=automationParameters(t),def=params.find(a=>a.key===key)||params[0];selectedCurve=def.key;const points=t.automation.curves[def.key]||[];
    d.modal('Automation · '+t.name,`<div class="workflow-form"><div class="workflow-grid"><label>Mode<select id="automationMode"><option value="off">OFF · Manuel</option><option value="read" ${t.automation.mode==='read'?'selected':''}>READ · Lire les courbes</option><option value="write" ${t.automation.mode==='write'?'selected':''}>WRITE · Enregistrer mes gestes</option></select></label><label>Paramètre<select id="automationTarget">${params.map(a=>`<option value="${a.key}" ${a.key===def.key?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label></div><svg id="automationCurve" class="automation-editor" viewBox="0 0 800 180" preserveAspectRatio="none" aria-label="Courbe d’automation"><path d="M0 90H800M0 179H800"/><polyline points="${[{bar:0,value:pointValue(points,0,def.value)},...points,{bar:p().bars,value:pointValue(points,p().bars,def.value)}].map(a=>`${a.bar/p().bars*800},${180-(a.value-def.min)/(def.max-def.min)*180}`).join(' ')}"/>${points.map(a=>`<circle cx="${a.bar/p().bars*800}" cy="${180-(a.value-def.min)/(def.max-def.min)*180}" r="4"/>`).join('')}</svg><small>Clique dans le graphique pour ajouter un point. La largeur correspond à toute la session (${p().bars} mesures).</small><div class="workflow-grid"><label>Mesure<input id="automationBar" type="number" min="1" max="${p().bars+1}" step=".0625" value="${(engine().getPosition()/16+1).toFixed(3)}"></label><label>Valeur (${def.min} à ${def.max})<input id="automationValue" type="number" min="${def.min}" max="${def.max}" step="any" value="${def.value}"></label></div><div class="workflow-row"><button class="primary-btn" id="addAutomationPoint">Ajouter / remplacer un point</button><button class="outline-btn" id="clearAutomation">Effacer cette courbe</button></div><div class="automation-points">${points.map((a,i)=>`<div><span>Mesure ${(a.bar+1).toFixed(3)}</span><strong>${a.value.toFixed(3)}</strong><button data-delete-auto-point="${i}">×</button></div>`).join('')||'<p>Aucun point.</p>'}</div><p>READ suit les courbes à la lecture et à l’export. WRITE enregistre les mouvements des faders, panoramiques, envois et paramètres proposés ici. Le calcul des courbes utilise l’horloge audio.</p></div>`,'WARLIKE / AUTOMATION');
    $('automationMode').onchange=e=>{d.checkpoint();t.automation.mode=e.target.value;d.changed(true);};$('automationTarget').onchange=e=>automationModal(id,e.target.value);
    const add=(bar,value)=>{if(!Number.isFinite(bar)||!Number.isFinite(value))return;d.checkpoint();putPoint(t,def.key,Math.max(0,Math.min(p().bars,bar)),Math.max(def.min,Math.min(def.max,value)),def.value);if(t.automation.mode==='off')t.automation.mode='read';d.changed(true);automationModal(id,def.key);};
    $('addAutomationPoint').onclick=()=>add(Number($('automationBar').value)-1,Number($('automationValue').value));
    $('automationCurve').onpointerdown=e=>{const r=e.currentTarget.getBoundingClientRect();add((e.clientX-r.left)/r.width*p().bars,def.max-(e.clientY-r.top)/r.height*(def.max-def.min));};
    $('clearAutomation').onclick=()=>{d.checkpoint();delete t.automation.curves[def.key];d.changed(true);automationModal(id,def.key);};
    for(const b of document.querySelectorAll('[data-delete-auto-point]'))b.onclick=()=>{d.checkpoint();points.splice(Number(b.dataset.deleteAutoPoint),1);d.changed(true);automationModal(id,def.key);};
  }
  function controlAutomation(e){if(!engine().playing)return;const el=e.target;let t,key,value=Number(el.value);if(!Number.isFinite(value))return;
    if(el.dataset.volume||el.dataset.volumeNumber){t=p().tracks.find(t=>t.id===(el.dataset.volume||el.dataset.volumeNumber));key='volume';}else if(el.dataset.pan){t=p().tracks.find(t=>t.id===el.dataset.pan);key='pan';}else if(el.dataset.sendLevel){const [id,sid]=el.dataset.sendLevel.split(':');t=p().tracks.find(t=>t.id===id);key='send:'+sid;}else if(el.dataset.param){const [target,param]=el.dataset.param.split('.');if(target==='instrument')return;const owner=el.closest('[data-plugin-track]');t=owner?p().tracks.find(t=>t.id===owner.dataset.pluginTrack):track();key=target+':'+param;}
    if(t?.automation?.mode==='write'&&key){const def=automationParameters(t).find(a=>a.key===key);if(def)putPoint(t,key,engine().getPosition()/16,value,def.value);}
  }
  document.addEventListener('input',controlAutomation,{capture:true});
  function exportModal(){d.modal('Exporter le morceau',`<div class="workflow-form"><div class="workflow-grid"><label>Destination<select id="exportMode"><option value="mix">Mix stéréo</option><option value="track">Piste / bus sélectionné</option><option value="stems">Toutes les pistes et bus · ZIP</option><option value="buses">Bus uniquement · ZIP</option></select></label><label>Traitements<select id="exportProcessing"><option value="wet">Avec les effets choisis</option><option value="clean">Sans les inserts</option></select></label><label>Fréquence<select id="exportRate"><option value="44100">44,1 kHz</option><option value="48000" selected>48 kHz</option><option value="96000">96 kHz</option></select></label><label>Résolution<select id="exportBits"><option value="16">16 bits PCM</option><option value="24" selected>24 bits PCM</option><option value="32">32 bits flottants</option></select></label><label>Début (mesure)<input id="exportStart" type="number" min="1" max="${p().bars}" value="1" step=".0625"></label><label>Fin exclue (mesure)<input id="exportEnd" type="number" min="1" max="${p().bars+1}" value="${p().bars+1}" step=".0625"></label></div><label class="workflow-check"><input id="exportTail" type="checkbox" checked> Inclure les queues d’effets</label><label class="workflow-check"><input id="exportDither" type="checkbox"> Dither TPDF pour le PCM 16 / 24 bits</label><p>Les fichiers d’un même export ont le même début et la même durée. Les stems de bus contiennent les pistes qui y sont routées. Le mix inclut le master ; les stems sont pris avant les inserts du master.</p><button id="runExport" class="primary-btn">Lancer l’export</button><button id="cancelExport" class="text-btn" hidden>Arrêter après le fichier en cours</button><a id="downloadRendered" class="primary-btn export-ready-link" hidden>Télécharger le rendu</a><output id="exportProgress"></output></div>`,'WARLIKE / BOUNCE');
    showExportLink();$('runExport').onclick=async()=>{if(exporting||d.getRecordState().recording)return;const options={sampleRate:Number($('exportRate').value),bits:Number($('exportBits').value),startBar:Number($('exportStart').value)-1,endBar:Number($('exportEnd').value)-1,tail:$('exportTail').checked,dither:$('exportDither').checked,clean:$('exportProcessing').value==='clean'},mode=$('exportMode').value;if(options.startBar<0||options.endBar>p().bars||options.endBar<=options.startBar){d.toast('Choisis une plage valide.');return;}let destinations=mode==='mix'?[null]:mode==='track'?[track()]:p().tracks.filter(t=>mode==='buses'?t.type==='bus':true);if(!destinations.length){d.toast('Crée au moins un bus à exporter.');return;}exporting=true;let cancelled=false;$('runExport').disabled=true;$('cancelExport').hidden=false;$('cancelExport').onclick=()=>cancelled=true;const files=[];
      try{for(let i=0;i<destinations.length;i++){if(cancelled)break;const t=destinations[i];if($('exportProgress'))$('exportProgress').textContent=`Rendu ${i+1}/${destinations.length} · ${t?.name||'Mix stéréo'}…`;const data=await engine().exportWav({...options,captureId:t?.id||null});files.push({name:safe(p().name)+'_'+safe(t?.name||'Mix')+'.wav',data});}if(!files.length)return;const archive=['stems','buses'].includes(mode),filename=archive?safe(p().name)+'_stems.zip':files[0].name,blob=archive?zipFiles(files):new Blob([files[0].data],{type:'audio/wav'});if(preparedExport)URL.revokeObjectURL(preparedExport.url);preparedExport={url:URL.createObjectURL(blob),filename};showExportLink();if($('exportProgress'))$('exportProgress').textContent=`${files.length} fichier(s) prêt(s) · ${options.sampleRate/1000} kHz / ${options.bits} bits${cancelled?' · Export interrompu':''}`;d.toast('Rendu prêt à télécharger.');}catch(error){d.toast('Export impossible : '+error.message);}finally{exporting=false;if($('runExport'))$('runExport').disabled=false;if($('cancelExport'))$('cancelExport').hidden=true;}
    };
  }
  function renderMastering(){if(analysisProject!==p()){lastAnalysis=null;analysisProject=p();}const root=$('masteringView');if(!root)return;root.querySelector('.loudness-analysis')?.remove();const fmt=n=>Number.isFinite(n)?n.toFixed(1):'−∞';root.insertAdjacentHTML('beforeend',`<section class="loudness-analysis"><div><strong>ANALYSE DU MIX</strong><small>LUFS intégrés · K-weighting et gating · stéréo</small></div><div class="loudness-values"><span>LUFS-I<strong>${lastAnalysis?fmt(lastAnalysis.integrated):'—'}</strong></span><span>LUFS-S MAX<strong>${lastAnalysis?fmt(lastAnalysis.shortMax):'—'}</strong></span><span>CRÊTE dBFS<strong>${lastAnalysis?fmt(lastAnalysis.samplePeak):'—'}</strong></span><span>CRÊTE 4× ESTIMÉE<strong>${lastAnalysis?fmt(lastAnalysis.estimatedPeak):'—'}</strong></span></div><div class="workflow-row"><button class="outline-btn" id="analyseMix" ${analysing?'disabled':''}>${analysing?'Analyse en cours…':'Analyser le mix complet'}</button><label>Cible LUFS<input id="loudnessTarget" type="number" min="-30" max="-6" step="1" value="-14"></label><button class="outline-btn" id="adjustLoudness" ${!lastAnalysis||!Number.isFinite(lastAnalysis.integrated)?'disabled':''}>Ajuster le gain avant chaîne</button></div><p>Réanalyse après modification du mix. La crête interpolée est une estimation et ne remplace pas un mesureur true-peak certifié. La cible reste ton choix ; aucun plugin n’est ajouté.</p><output id="analysisStatus"></output></section>`);
    $('analyseMix').onclick=async()=>{if(analysing)return;analysing=true;renderMastering();let worker;try{const buffer=await engine().renderRange({sampleRate:48000,tail:true});const channels=Array.from({length:buffer.numberOfChannels},(_,i)=>buffer.getChannelData(i).slice());worker=new Worker(new URL('./loudness-worker.js?v=0.13.0',import.meta.url),{type:'module'});const result=await new Promise((resolve,reject)=>{worker.onmessage=({data})=>data.error?reject(Error(data.error)):resolve(data.result);worker.onerror=()=>reject(Error('Analyse audio interrompue.'));worker.postMessage({channels,sampleRate:48000},channels.map(c=>c.buffer));});lastAnalysis=result;d.toast('Analyse du mix terminée.');}catch(error){d.toast(error.message);}finally{worker?.terminate();analysing=false;renderMastering();}};
    $('adjustLoudness').onclick=()=>{if(!lastAnalysis||!Number.isFinite(lastAnalysis.integrated))return;const requested=Number($('loudnessTarget').value)-lastAnalysis.integrated,headroom=-1-lastAnalysis.estimatedPeak,change=Math.min(requested,headroom);d.checkpoint();p().masterVolume=Math.max(-48,Math.min(3,engine().masterVolume+change));d.changed(true);if($('analysisStatus'))$('analysisStatus').textContent='Gain ajusté avec marge de crête estimée. Réanalyse le résultat, surtout si la chaîne master compresse le signal.';};
  }
  function showExportLink(){const a=$('downloadRendered');if(a&&preparedExport){a.hidden=false;a.href=preparedExport.url;a.download=preparedExport.filename;a.textContent='Télécharger '+preparedExport.filename;}}
  async function devices(){if(!navigator.mediaDevices?.enumerateDevices)return [];return (await navigator.mediaDevices.enumerateDevices()).filter(a=>a.kind==='audioinput');}
  async function recordingModal(){const settings=recordingSettings(p().recording),a=setup(),list=await devices().catch(()=>[]);d.modal('Enregistrement audio',`<div class="workflow-form"><label>Entrée audio<select id="inputDevice"><option value="">Entrée système par défaut</option>${list.filter(a=>a.deviceId!=='default').map((v,i)=>`<option value="${esc(v.deviceId)}" ${v.deviceId===a.deviceId?'selected':''}>${esc(v.label||'Entrée '+(i+1))}</option>`).join('')}</select></label><button class="outline-btn" id="refreshInputs">Autoriser le micro / actualiser les entrées</button><label>Canal<select id="inputChannel"><option value="1">Entrée 1 · mono</option><option value="2" ${a.channel==='2'?'selected':''}>Entrée 2 · mono</option><option value="stereo" ${a.channel==='stereo'?'selected':''}>Entrées 1–2 · stéréo</option></select></label><label>Gain numérique (dB)<input id="workflowMicGain" type="number" min="0" max="24" step=".5" value="${settings.gainDb}"></label><label class="workflow-check"><input id="inputMonitor" type="checkbox" ${a.monitor?'checked':''}> Écouter l’entrée à travers les inserts de la piste</label><small>Utilise un casque pour ce monitoring. L’enregistrement PCM conserve l’entrée avant les effets.</small><label class="workflow-check"><input id="knownCompensation" type="checkbox" ${p().delayCompensation!==false?'checked':''}> Compenser les délais connus des compresseurs dans le routage</label><label class="workflow-check"><input id="keepTakes" type="checkbox" ${a.keepTakes!==false?'checked':''}> Conserver les prises superposées dans des playlists</label><label class="workflow-check"><input id="workflowAutoLevel" type="checkbox" ${settings.autoLevel?'checked':''}> Ajuster le gain du clip après la prise</label><label>Compensation d’enregistrement (ms)<input id="recordLatency" type="number" min="-500" max="1000" step=".1" value="${a.latencyMs||0}"></label><small>Une valeur positive avance la prise. Latence de sortie annoncée par le navigateur : ${engine().ctx?(((engine().ctx.baseLatency||0)+(engine().ctx.outputLatency||0))*1000).toFixed(1)+' ms':'disponible après activation audio'}. La mesure d’entrée demande un bouclage réel.</small><button class="outline-btn" id="calibrateAudio">Mesurer par bouclage sortie → entrée</button><p>Pour la mesure, relie une sortie ligne de l’interface à l’entrée sélectionnée. Un signal bref sera envoyé à faible niveau. Coupe le monitoring direct matériel et le monitoring logiciel pendant ce test.</p><output id="calibrationResult"></output><button class="primary-btn" id="saveAudioSetup">Appliquer les réglages</button></div>`,'WARLIKE / RECORDING');
    const collect=()=>({deviceId:$('inputDevice').value,channel:$('inputChannel').value,monitor:$('inputMonitor').checked,keepTakes:$('keepTakes').checked,latencyMs:Math.max(-500,Math.min(1000,Number($('recordLatency').value)||0))});
    $('saveAudioSetup').onclick=()=>{d.checkpoint();p().audioSetup=collect();p().delayCompensation=$('knownCompensation').checked;p().recording=recordingSettings({gainDb:Number($('workflowMicGain').value),autoLevel:$('workflowAutoLevel').checked});const rec=d.getRecordState().recording;if(rec)rec.graph.setGain(p().recording.gainDb);d.changed();$('modal').close();};
    $('refreshInputs').onclick=async()=>{try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(t=>t.stop());p().audioSetup=collect();await recordingModal();}catch(error){d.toast('Entrée indisponible : '+error.message);}};
    $('calibrateAudio').onclick=async()=>{const button=$('calibrateAudio'),a=collect();button.disabled=true;let stream,graph,capture;try{await engine().init();stream=await navigator.mediaDevices.getUserMedia({audio:{...(a.deviceId?{deviceId:{exact:a.deviceId}}:{}),echoCancellation:false,noiseSuppression:false,autoGainControl:false}});graph=createRecordingGraph(engine().ctx,stream,0);capture=await createPcmCapture(engine().ctx,graph.inputNode,{channel:a.channel});const ctx=engine().ctx,start=ctx.currentTime+.1,pulse=ctx.createBuffer(1,Math.round(ctx.sampleRate*.02),ctx.sampleRate),data=pulse.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=.12*Math.sin(2*Math.PI*997*i/ctx.sampleRate)*Math.sin(Math.PI*i/data.length)**2;const source=ctx.createBufferSource();source.buffer=pulse;source.connect(ctx.destination);capture.start(start);source.start(start+.25);await new Promise(resolve=>setTimeout(resolve,1300));const buffer=await capture.stop(),signal=buffer.getChannelData(0);let best=0,position=0;for(let i=0;i<signal.length;i++)if(Math.abs(signal[i])>best){best=Math.abs(signal[i]);position=i;}if(best<.005)throw Error('Aucun retour détecté. Vérifie le câble et l’entrée.');const ms=(position/ctx.sampleRate-.25-.01)*1000;if(ms<0||ms>1000)throw Error('Mesure incohérente. Vérifie le routage de bouclage.');$('recordLatency').value=ms.toFixed(1);$('calibrationResult').textContent='Décalage estimé : '+ms.toFixed(1)+' ms. Applique les réglages pour l’utiliser.';}catch(error){d.toast(error.message);}finally{capture?.dispose();graph?.dispose();stream?.getTracks().forEach(t=>t.stop());if($('calibrateAudio'))$('calibrateAudio').disabled=false;}};
  }
  async function record(){if(d.getRecordState().recording){await stopRecording();return;}if(d.getRecordState().recordFinalizing||d.getRecordState().micPending)return;let stream,graph,capture;d.setFlags({micPending:true});d.updateTransport();
    try{stopTest();await engine().init();if(!navigator.mediaDevices?.getUserMedia||!engine().ctx.audioWorklet)throw Error('La capture PCM nécessite HTTPS et un navigateur compatible AudioWorklet.');const a=setup();stream=await navigator.mediaDevices.getUserMedia({audio:{...(a.deviceId?{deviceId:{exact:a.deviceId}}:{}),echoCancellation:false,noiseSuppression:false,autoGainControl:false}});let t=track();if(t.type!=='audio')t=d.addTrack('audio');engine().pause();engine().patternMode=null;engine().clipPreview=null;const start=engine().position,previousLoop=engine().loop;engine().loop=false;graph=createRecordingGraph(engine().ctx,stream,recordingSettings(p().recording).gainDb);capture=await createPcmCapture(engine().ctx,graph.inputNode,{channel:a.channel});if(a.monitor)graph.monitor(engine().channels.get(t.id).input);const rec={stream,graph,capture,track:t,start,previousLoop,options:clone(a),autoLevel:recordingSettings(p().recording).autoLevel};d.setRecording(rec);d.setFlags({micPending:false});engine().recordingTrackId=t.id;await engine().play();capture.start(engine().startTime+start*engine().stepDuration);rec.timer=setInterval(()=>{if(engine().getPosition()>p().bars*16-32&&p().bars<MAX_BARS){p().bars=fitSession(p().bars,p().bars+16);d.changed(true);}if(capture.frames/engine().ctx.sampleRate>1200){d.toast('Prise arrêtée après 20 minutes.');stopRecording();}},500);d.updateTransport();d.toast('Capture PCM active. Stop termine la prise.');
    }catch(error){capture?.dispose();graph?.dispose();stream?.getTracks().forEach(t=>t.stop());engine().recordingTrackId=null;d.setRecording(null);d.setFlags({micPending:false,recordFinalizing:false});d.toast('Enregistrement impossible : '+error.message);d.updateTransport();}
  }
  async function stopRecording(){const rec=d.getRecordState().recording;if(!rec)return;d.setRecording(null);d.setFlags({recordFinalizing:true});clearInterval(rec.timer);engine().pause();engine().recordingTrackId=null;engine().loop=rec.previousLoop;engine().position=rec.start;d.updateTransport();
    try{const buffer=await rec.capture.stop();graphCleanup(rec);const data=encodeWav(buffer,{bits:32}),levels=measureBuffer(buffer),gain=rec.autoLevel?normalisationGain(levels):{gainDb:0},name='Prise '+new Date().toLocaleTimeString('fr-FR'),id=uid(),placement=recordingPlacement(rec.start/16,buffer.duration,p().bpm,rec.options.latencyMs);if(placement.length<1/10000){d.toast('Prise trop courte.');return;}assets().set(id,{name,data,buffer,levels});d.checkpoint();const c={id:uid(),name,audioId:id,gainDb:gain.gainDb,recorded:true,...placement};recordTake(rec.track,c,p().bpm,uid,rec.options.keepTakes!==false);p().bars=fitSession(p().bars,c.start+c.length);d.selectTrack(rec.track.id,c.id);d.changed(true);d.toast('Prise PCM enregistrée · original avant effets conservé.');}catch(error){d.toast('Capture impossible : '+error.message);}finally{graphCleanup(rec);d.setFlags({recordFinalizing:false});d.updateTransport();}
  }
  function graphCleanup(rec){rec.graph.dispose();rec.stream.getTracks().forEach(t=>t.stop());}
  function stopTest(){testGraph?.dispose();testGraph=null;}
  const dbGet=key=>new Promise((resolve,reject)=>{const db=d.getDB();if(!db){reject(Error('Stockage local indisponible.'));return;}const req=db.transaction('sessions').objectStore('sessions').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
  const dbPut=(key,value)=>new Promise((resolve,reject)=>{const tx=d.getDB().transaction('sessions','readwrite');tx.objectStore('sessions').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});
  async function snapshot(name='Sauvegarde automatique',manual=false){if(!d.getDB()||!manual&&Date.now()-snapshotTime<120000)return;const project=clone(p()),ids=[...audioAssetIds(project)];for(const id of ids){const a=assets().get(id);if(a&&!await dbGet('media:'+id))await dbPut('media:'+id,{id,name:a.name,data:a.data});}const list=await dbGet('versions')||[];list.unshift({id:uid(),date:Date.now(),name,project,assetIds:ids});await dbPut('versions',list.slice(0,12));snapshotTime=Date.now();}
  async function versionsModal(){const list=await dbGet('versions').catch(()=>[]);d.modal('Versions de la session',`<div class="workflow-form"><div class="workflow-row"><input id="versionName" placeholder="Nom de cette version" maxlength="80"><button class="primary-btn" id="saveVersion">Créer un point de restauration</button></div><p>Douze points sont conservés sur cet appareil, avec les audios nécessaires. Télécharge un projet .chayah pour une copie indépendante.</p><div class="version-list">${(list||[]).map(v=>`<button class="outline-btn" data-restore-version="${v.id}"><strong>${esc(v.name)}</strong><span>${new Date(v.date).toLocaleString('fr-FR')} · ${esc(v.project.name)}</span></button>`).join('')||'<p>Aucune version enregistrée.</p>'}</div></div>`,'WARLIKE / HISTORIQUE');$('saveVersion').onclick=async()=>{try{await snapshot($('versionName').value.trim()||'Version manuelle',true);await versionsModal();}catch(error){d.toast('Version non sauvegardée : '+error.message);}};
    for(const b of document.querySelectorAll('[data-restore-version]'))b.onclick=async()=>{if(d.getRecordState().recording)return;const v=list.find(v=>v.id===b.dataset.restoreVersion);try{const candidate=clone(v.project);d.validateProject(candidate);await engine().init();for(const id of v.assetIds)if(!assets().has(id)){const a=await dbGet('media:'+id);if(!a)throw Error('Audio manquant dans cette version.');assets().set(id,{...a,buffer:await engine().ctx.decodeAudioData(a.data.slice(0))});}engine().stop();d.checkpoint();d.setProject(candidate);d.selectTrack(candidate.tracks[0].id,candidate.tracks[0].clips[0]?.id);d.changed(true);$('modal').close();d.toast('Version restaurée. Annuler retrouve la session précédente.');}catch(error){d.toast(error.message);}};
  }
  async function freezeTrack(id){const t=p().tracks.find(t=>t.id===id);if(!t||t.type==='bus'){d.toast('Gèle une piste source audio ou instrument.');return;}if(t.frozenTrack){d.checkpoint();Object.assign(t,clone(t.frozenTrack));delete t.frozenTrack;d.changed(true);return;}if(d.getRecordState().recording)return;d.toast('Calcul de la piste gelée…');try{const buffer=await engine().renderRange({captureId:t.id,preFader:true,tail:false,sampleRate:engine().ctx?.sampleRate===48000?48000:44100}),audioId=uid();assets().set(audioId,{name:t.name+' · gel',buffer,data:encodeWav(buffer,{bits:32})});d.checkpoint();const original={type:t.type,instrument:clone(t.instrument),effects:clone(t.effects),inserts:clone(t.inserts),clips:clone(t.clips),automation:clone(t.automation),playlists:clone(t.playlists||[]),activePlaylist:t.activePlaylist};t.frozenTrack=original;t.type='audio';t.clips=[{id:uid(),name:t.name+' · gel',start:0,length:p().bars,audioId}];t.playlists=[];delete t.activePlaylist;for(const state of Object.values(t.effects))state.enabled=false;t.inserts=[];t.automation.curves=Object.fromEntries(Object.entries(t.automation.curves||{}).filter(([key])=>['volume','pan'].includes(key)||key.startsWith('send:')));d.selectTrack(t.id,t.clips[0].id);d.changed(true);d.toast('Piste gelée. Dégeler retrouve les réglages et les clips originaux.');}catch(error){d.toast(error.message);}}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-create-bus],[data-playlists-track],[data-automation-track],[data-audio-properties],[data-crossfade],[data-freeze-track],[data-send-remove],[data-send-toggle]');if(!b)return;
    if(b.hasAttribute('data-create-bus')){busModal();return;}if(b.dataset.playlistsTrack){playlistsModal(b.dataset.playlistsTrack);return;}if(b.dataset.automationTrack){automationModal(b.dataset.automationTrack);return;}if(b.hasAttribute('data-audio-properties')){audioProperties();return;}if(b.dataset.freezeTrack){freezeTrack(b.dataset.freezeTrack);return;}if(b.hasAttribute('data-crossfade')){try{d.checkpoint();const duration=applyCrossfade(track(),clip().id,p().bpm);d.changed(true);d.toast('Fondu croisé de '+Math.round(duration*1000)+' ms.');}catch(error){d.toast(error.message);}return;}
    const [id,sid]=(b.dataset.sendRemove||b.dataset.sendToggle).split(':'),t=p().tracks.find(t=>t.id===id);d.checkpoint();if(b.dataset.sendRemove)t.sends=t.sends.filter(s=>s.id!==sid);else{const send=t.sends.find(s=>s.id===sid);send.enabled=!send.enabled;}d.changed(true);
  });
  document.addEventListener('change',e=>{const el=e.target;if(el.dataset.routeOutput){const t=p().tracks.find(t=>t.id===el.dataset.routeOutput);if(!routeAllowed(p().tracks,t.id,el.value)){d.toast('Ce routage créerait une boucle audio.');el.value=t.output;return;}d.checkpoint();t.output=el.value;d.changed(true);}if(el.dataset.sendAdd&&el.value){const t=p().tracks.find(t=>t.id===el.dataset.sendAdd);if(!routeAllowed(p().tracks,t.id,el.value))return;d.checkpoint();t.sends.push({id:uid(),target:el.value,level:-12,pre:false,enabled:true});d.changed(true);}if(el.dataset.sendPosition){const [id,sid]=el.dataset.sendPosition.split(':'),t=p().tracks.find(t=>t.id===id);d.checkpoint();t.sends.find(s=>s.id===sid).pre=el.value==='pre';d.changed(true);}});
  document.addEventListener('pointerdown',e=>{if(e.target.dataset.sendLevel)d.checkpoint();});
  document.addEventListener('input',e=>{if(e.target.dataset.sendLevel){const [id,sid]=e.target.dataset.sendLevel.split(':'),t=p().tracks.find(t=>t.id===id),s=t.sends.find(s=>s.id===sid);s.level=Number(e.target.value);const label=document.querySelector(`[data-send-db="${sid}"]`);if(label)label.textContent=s.level.toFixed(1)+' dB';d.changed();}});
  function updateFrame(){if(!engine().playing)return;const bar=engine().getPosition()/16;for(const t of p().tracks)if(t.automation?.mode==='read'){for(const key of ['volume','pan']){const points=t.automation.curves[key];if(!points?.length)continue;const value=pointValue(points,bar,t[key]);if(key==='volume'){for(const node of document.querySelectorAll(`[data-db="${t.id}"]`))node.textContent=value.toFixed(1)+' dB';for(const node of document.querySelectorAll(`[data-volume="${t.id}"]`))if(node!==document.activeElement)node.value=value;}}}}
  return {renderMastering,renderInspector,renderMixer,renderAudioEditor,renderTimeline,exportModal,recordingModal,record,stopRecording,versionsModal,snapshot,updateFrame,stopTest};
}
